    .insert(maritimeVessels)
    .values(
      records.map((record) => ({
        id: record.vessel_id,
        workspaceId,
        vesselName: record.vessel_name,
        imo: record.imo,
        vesselType: record.vessel_type,
        dwt: record.dwt,
        flag: record.flag,
        yearBuilt: record.year_built,
        capacity: record.capacity,
        homePort: record.home_port,
        operationalStatus: record.operational_status,
        raw: record,
        updatedAt: now,
